const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define locations
  const airportCoords = [85.8245, 20.2441]; // Biju Patnaik Airport, Bhubaneswar
  const saheedNagarCoords = [85.848691, 20.290813]; // Saheed Nagar

  const airportPoint = ee.Geometry.Point(airportCoords);
  const saheedNagarPoint = ee.Geometry.Point(saheedNagarCoords);

  // Date range
  const startDate = '2019-04-30';
  const endDate = '2019-05-05';

  // Load VIIRS DNB monthly data (nighttime lights)
  const viirsDNB = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1_1')
    .filterDate(startDate, endDate)
    .select('avg_rad');

  const collectionSize = viirsDNB.size().getInfo();
  print(`VIIRS DNB Images in range: ${collectionSize}`);

  if (collectionSize === 0) {
    print('No VIIRS data found for date range.');
    print('C1');
    return;
  }

  // Get first and last images for the period
  const sortedCol = viirsDNB.sort('system:time_start');
  const firstImg = ee.Image(sortedCol.first());
  const lastImg = ee.Image(sortedCol.sort('system:time_start', false).first());

  // Get first date info
  const firstDate = firstImg.date().format('YYYY-MM-dd').getInfo();
  const lastDate = lastImg.date().format('YYYY-MM-dd').getInfo();
  print(`Date range: ${firstDate} to ${lastDate}`);

  // Sample brightness at Airport
  const airportFirst = firstImg.sample(airportPoint, 1000).first().getInfo();
  const airportLast = lastImg.sample(airportPoint, 1000).first().getInfo();

  // Sample brightness at Saheed Nagar
  const saheedFirst = firstImg.sample(saheedNagarPoint, 1000).first().getInfo();
  const saheedLast = lastImg.sample(saheedNagarPoint, 1000).first().getInfo();

  // Extract brightness values
  const airportBrightFirst = airportFirst.properties.avg_rad;
  const airportBrightLast = airportLast.properties.avg_rad;
  const saheedBrightFirst = saheedFirst.properties.avg_rad;
  const saheedBrightLast = saheedLast.properties.avg_rad;

  print(`Airport - Start: ${airportBrightFirst}, End: ${airportBrightLast}`);
  print(`Saheed Nagar - Start: ${saheedBrightFirst}, End: ${saheedBrightLast}`);

  // Check for valid data
  if (airportBrightFirst === null || airportBrightLast === null || 
      saheedBrightFirst === null || saheedBrightLast === null) {
    print('Invalid or missing brightness data at one or both locations.');
    print('C2');
    return;
  }

  // Calculate decrease (positive value = decrease, negative = increase)
  const airportDecrease = airportBrightFirst - airportBrightLast;
  const saheedDecrease = saheedBrightFirst - saheedBrightLast;

  print(`Airport brightness decrease: ${airportDecrease.toFixed(4)}`);
  print(`Saheed Nagar brightness decrease: ${saheedDecrease.toFixed(4)}`);

  // Check for NaN
  if (isNaN(airportDecrease) || isNaN(saheedDecrease)) {
    print('Calculation resulted in NaN.');
    print('C3');
    return;
  }

  // Compare: Did airport decrease more than Saheed Nagar?
  if (airportDecrease > saheedDecrease) {
    print('Airport brightness decreased more than Saheed Nagar.');
    print('A');
  } else {
    print('Airport brightness did not decrease more than Saheed Nagar.');
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
